import * as React from 'react'
import type { Token, Marked } from 'marked'
import { CodeBlock, codeLanguages, type CodeLanguage } from '@/components/ui/code-block'
import { productURL, clamp } from '@/components/ui/product-utils'
import { cn } from '@/lib/utils'
import { useTextStream, type TextStreamOptions } from '@/components/ui/text-stream'
export interface StreamingMarkdownProps
  extends Omit<React.ComponentProps<'div'>, 'children'>, TextStreamOptions {
  content: string
  streaming?: boolean
  breaks?: boolean
  allowImages?: boolean
  maxCharacters?: number
  renderCode?: (code: string, language: string) => React.ReactNode
  renderImage?: (image: { src: string; alt: string; title?: string }) => React.ReactNode
  /** An application renderer for fenced math, latex or mermaid blocks; no rendering engine is bundled. */
  renderMath?: (source: string) => React.ReactNode
  renderDiagram?: (source: string) => React.ReactNode
}
let engine: Promise<typeof import('marked')> | undefined
/** Decode character entities in an unattached text-only element; escape '<' before parsing. */
export function decodeMarkdownText(text: string) {
  if (!text.includes('&')) return text
  if (typeof document === 'undefined')
    return text.replace(
      /&(?:amp|lt|gt|quot|apos);/g,
      (entity) =>
        ({ '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&apos;': "'" })[entity]!,
    )
  const decoder = document.createElement('textarea')
  decoder.innerHTML = text.replace(/</g, '&lt;')
  return decoder.value
}
/** Lazily lexes Markdown into React elements. Raw HTML is displayed as text, never injected. */
export function StreamingMarkdown({
  content,
  streaming = false,
  textAnimation = 'typewriter',
  charactersPerSecond = 60,
  breaks = false,
  allowImages = true,
  maxCharacters = 150000,
  renderCode,
  renderImage,
  renderMath,
  renderDiagram,
  className,
  ...props
}: StreamingMarkdownProps) {
  const [parser, setParser] = React.useState<Marked | null>(null),
    [error, setError] = React.useState(''),
    limit = Math.floor(clamp(maxCharacters, 100, 1000000)),
    bounded = content.slice(0, limit)
  const { text: source, isRevealing } = useTextStream(bounded, {
    streaming,
    textAnimation,
    charactersPerSecond,
  })
  const busy = streaming || isRevealing
  React.useEffect(() => {
    let active = true
    ;(engine ??= import('marked')).then(
      (module) => {
        if (active) setParser(new module.Marked({ gfm: true }))
      },
      (failure) => {
        engine = undefined
        if (active)
          setError(failure instanceof Error ? failure.message : 'Markdown could not load.')
      },
    )
    return () => {
      active = false
    }
  }, [])
  const parsed = React.useMemo(() => {
    try {
      return { tokens: parser?.lexer(source, { gfm: true, breaks }) ?? null, error: '' }
    } catch (failure) {
      return {
        tokens: null,
        error: failure instanceof Error ? failure.message : 'Markdown could not be parsed.',
      }
    }
  }, [source, parser, breaks])
  const inline = (tokens: Token[] | undefined, fallback = ''): React.ReactNode =>
    tokens ? tokens.map((token, index) => render(token, `i${index}`)) : decodeMarkdownText(fallback)
  const render = (token: Token, key: string, depth = 0): React.ReactNode => {
    if (depth > 32) return null
    const nested = (tokens: Token[] | undefined, fallback = '') =>
      tokens
        ? tokens.map((t, index) => render(t, `${key}-${index}`, depth + 1))
        : decodeMarkdownText(fallback)
    switch (token.type) {
      case 'space':
      case 'def':
      case 'checkbox':
        return null
      case 'heading': {
        const Tag = `h${Math.min(6, Math.max(1, token.depth))}` as
          'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'
        return (
          <Tag
            key={key}
            className={cn(
              'mt-5 mb-2 font-semibold tracking-tight first:mt-0',
              token.depth === 1 ? 'text-2xl' : token.depth === 2 ? 'text-xl' : 'text-base',
            )}
          >
            {nested(token.tokens, token.text)}
          </Tag>
        )
      }
      case 'paragraph':
        return (
          <p key={key} className="my-3 leading-relaxed first:mt-0 last:mb-0">
            {nested(token.tokens, token.text)}
          </p>
        )
      case 'text':
        return <React.Fragment key={key}>{nested(token.tokens, token.text)}</React.Fragment>
      case 'escape':
        return <React.Fragment key={key}>{decodeMarkdownText(token.text)}</React.Fragment>
      case 'strong':
        return <strong key={key}>{nested(token.tokens, token.text)}</strong>
      case 'em':
        return <em key={key}>{nested(token.tokens, token.text)}</em>
      case 'del':
        return <del key={key}>{nested(token.tokens, token.text)}</del>
      case 'codespan':
        return (
          <code key={key} className="rounded bg-muted px-1 py-0.5 font-mono text-[.85em]">
            {token.text}
          </code>
        )
      case 'br':
        return <br key={key} />
      case 'hr':
        return <hr key={key} className="my-5 border-border" />
      case 'blockquote':
        return (
          <blockquote key={key} className="my-4 border-s-2 ps-4 text-muted-foreground">
            {nested(token.tokens, token.text)}
          </blockquote>
        )
      case 'code': {
        const language = (token.lang ?? 'text').split(/\s/)[0].toLowerCase()
        return (
          <div key={key} className="my-4 min-w-0">
            {language === 'mermaid' && renderDiagram ? (
              renderDiagram(token.text)
            ) : ['math', 'latex'].includes(language) && renderMath ? (
              renderMath(token.text)
            ) : renderCode ? (
              renderCode(token.text, language)
            ) : (
              <CodeBlock
                code={token.text}
                language={
                  codeLanguages.includes(language as CodeLanguage)
                    ? (language as CodeLanguage)
                    : 'text'
                }
                lineNumbers={false}
              />
            )}
          </div>
        )
      }
      case 'link': {
        const href = productURL(token.href)
        return href ? (
          <a
            key={key}
            href={href}
            title={token.title ?? undefined}
            target={/^https?:/i.test(href) ? '_blank' : undefined}
            rel="noopener noreferrer"
            className="text-primary underline decoration-primary/40 underline-offset-4 hover:decoration-primary"
          >
            {nested(token.tokens, token.text)}
          </a>
        ) : (
          <span key={key}>{nested(token.tokens, token.text)}</span>
        )
      }
      case 'image': {
        const src = allowImages && productURL(token.href, true)
        return src ? (
          <React.Fragment key={key}>
            {renderImage?.({ src, alt: token.text, title: token.title ?? undefined }) ?? (
              <img
                src={src}
                alt={token.text}
                title={token.title ?? undefined}
                loading="lazy"
                className="my-3 max-h-[32rem] max-w-full rounded-lg object-contain"
              />
            )}
          </React.Fragment>
        ) : (
          <span key={key} className="text-muted-foreground">
            {token.text}
          </span>
        )
      }
      case 'list': {
        const Tag = token.ordered ? 'ol' : 'ul'
        return (
          <Tag
            key={key}
            start={token.ordered ? Number(token.start) || 1 : undefined}
            className={cn('my-3 space-y-1 ps-6', token.ordered ? 'list-decimal' : 'list-disc')}
          >
            {token.items.map(
              (item: { tokens: Token[]; task?: boolean; checked?: boolean }, index: number) => (
                <li key={`${key}-${index}`} className={cn(item.task && 'list-none')}>
                  {item.task && (
                    <input
                      type="checkbox"
                      checked={!!item.checked}
                      readOnly
                      tabIndex={-1}
                      aria-label={item.checked ? 'Completed task' : 'Incomplete task'}
                      className="me-2 align-middle accent-primary"
                    />
                  )}
                  {nested(item.tokens)}
                </li>
              ),
            )}
          </Tag>
        )
      }
      case 'table':
        return (
          <div key={key} className="my-4 max-w-full overflow-x-auto rounded-lg border">
            <table className="w-full border-collapse text-sm">
              <thead className="bg-muted/50">
                <tr>
                  {token.header.map((cell: { tokens: Token[] }, index: number) => (
                    <th
                      key={index}
                      className="border-b px-3 py-2 font-medium"
                      style={{ textAlign: token.align[index] ?? 'start' }}
                    >
                      {nested(cell.tokens)}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {token.rows.map((row: { tokens: Token[] }[], index: number) => (
                  <tr key={index} className="border-b last:border-0">
                    {row.map((cell, column) => (
                      <td
                        key={column}
                        className="px-3 py-2"
                        style={{ textAlign: token.align[column] ?? 'start' }}
                      >
                        {inline(cell.tokens)}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )
      case 'html':
        return <span key={key}>{token.text}</span>
      default:
        return (
          <React.Fragment key={key}>
            {typeof token.raw === 'string' ? token.raw : ''}
          </React.Fragment>
        )
    }
  }
  return (
    <div
      {...props}
      data-slot="streaming-markdown"
      aria-busy={busy}
      data-revealing={isRevealing}
      className={cn('min-w-0 break-words text-sm text-foreground', className)}
    >
      {error || parsed.error ? (
        <>
          <p role="alert" className="text-destructive">
            {error || parsed.error}
          </p>
          <p className="whitespace-pre-wrap">{source}</p>
        </>
      ) : parsed.tokens ? (
        parsed.tokens.map((token, index) => render(token, `b${index}`))
      ) : (
        <p className="whitespace-pre-wrap">{source}</p>
      )}
      {content.length > limit && (
        <p role="status" className="mt-3 text-xs text-muted-foreground">
          Preview limited to {limit.toLocaleString()} characters.
        </p>
      )}
      {busy && (
        <span
          role="status"
          aria-label="Response streaming"
          className="mt-2 inline-block size-2 animate-pulse rounded-full bg-primary"
        />
      )}
    </div>
  )
}

import * as React from 'react'
import { Check, Copy, Download, WrapText } from 'lucide-react'
import type { ThemedTokenWithVariants } from 'shiki/core'
import { Button } from '@/components/ui/button'
import { highlightCode, type CodeLanguage } from '@/components/ui/code-highlighter'
import { useControllableState } from '@/components/ui/util'
import { cn } from '@/lib/utils'

export { codeLanguages, type CodeLanguage } from '@/components/ui/code-highlighter'
export interface CodeBlockProps extends Omit<React.ComponentProps<'figure'>, 'onCopy'> {
  code: string
  language?: CodeLanguage
  filename?: string
  label?: string
  lineNumbers?: boolean
  startLine?: number
  highlightedLines?: number[]
  wrap?: boolean
  defaultWrap?: boolean
  onWrapChange?: (wrap: boolean) => void
  copyable?: boolean
  downloadable?: boolean
  maxHighlightLength?: number
  onCopy?: (code: string) => void | Promise<void>
}
interface CodeContext {
  code: string
  filename: string
  language: CodeLanguage
  lineNumbers: boolean
  startLine: number
  highlightedLines: number[]
  wrap: boolean
  setWrap: (value: boolean) => void
  copyable: boolean
  downloadable: boolean
  onCopy?: CodeBlockProps['onCopy']
  tokens: ThemedTokenWithVariants[][] | null
  status: string
  setStatus: (status: string) => void
}
const Context = React.createContext<CodeContext | null>(null)
function useCode() {
  const context = React.useContext(Context)
  if (!context) throw new Error('CodeBlock parts need CodeBlock.')
  return context
}
/** Shows source as escaped React text and lazily highlights bounded code with grammar-specific imports. */
export function CodeBlock({
  code,
  language = 'text',
  filename = '',
  label = 'Code example',
  lineNumbers = true,
  startLine = 1,
  highlightedLines = [],
  wrap,
  defaultWrap = false,
  onWrapChange,
  copyable = true,
  downloadable = false,
  maxHighlightLength = 100000,
  onCopy,
  className,
  children,
  ...props
}: CodeBlockProps) {
  const [wrapped, setWrap] = useControllableState({
      value: wrap,
      defaultValue: defaultWrap,
      onChange: onWrapChange,
    }),
    [result, setResult] = React.useState<{
      code: string
      language: CodeLanguage
      tokens: ThemedTokenWithVariants[][]
    } | null>(null),
    [status, setStatus] = React.useState('')
  React.useEffect(() => {
    let stale = false
    setStatus('')
    setResult(null)
    if (
      code.length >
      Math.min(
        500000,
        Math.max(0, Number.isFinite(maxHighlightLength) ? maxHighlightLength : 100000),
      )
    ) {
      setStatus('Syntax highlighting skipped for large content.')
      return
    }
    if (language === 'text') return
    highlightCode(code, language)
      .then((tokens) => {
        if (!stale) setResult({ code, language, tokens })
      })
      .catch(() => {
        if (!stale) setStatus('Syntax highlighting unavailable. Plain text is shown.')
      })
    return () => {
      stale = true
    }
  }, [code, language, maxHighlightLength])
  const tokens = result?.code === code && result.language === language ? result.tokens : null
  return (
    <Context.Provider
      value={{
        code,
        filename,
        language,
        lineNumbers,
        startLine: Number.isFinite(startLine) ? Math.max(1, Math.floor(startLine)) : 1,
        highlightedLines,
        wrap: wrapped,
        setWrap,
        copyable,
        downloadable,
        onCopy,
        tokens,
        status,
        setStatus,
      }}
    >
      <figure
        {...props}
        aria-label={label}
        data-slot="code-block"
        className={cn('min-w-0 overflow-hidden rounded-xl border bg-muted/20', className)}
      >
        {children ?? (
          <>
            <CodeBlockHeader />
            <CodeBlockContent />
          </>
        )}
        <p
          role="status"
          className={cn(status ? 'border-t px-4 py-2 text-xs text-muted-foreground' : 'sr-only')}
        >
          {status}
        </p>
      </figure>
    </Context.Provider>
  )
}
/** Provides independently composable filename, wrapping, copy, and local download actions. */
export function CodeBlockHeader({ className, ...props }: React.ComponentProps<'figcaption'>) {
  const c = useCode()
  const copy = async () => {
    try {
      if (c.onCopy) await c.onCopy(c.code)
      else await navigator.clipboard.writeText(c.code)
      c.setStatus('Code copied.')
    } catch {
      c.setStatus('Could not copy code.')
    }
  }
  return (
    <figcaption
      {...props}
      className={cn('flex flex-wrap items-center gap-2 border-b px-3 py-2', className)}
    >
      <span className="min-w-0 flex-1 truncate text-xs font-medium">
        {c.filename || c.language}
      </span>
      <Button
        type="button"
        variant="ghost"
        size="icon"
        aria-label="Wrap code"
        aria-pressed={c.wrap}
        onClick={() => c.setWrap(!c.wrap)}
      >
        <WrapText className="size-4" />
      </Button>
      {c.copyable && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label="Copy code"
          onClick={() => void copy()}
        >
          {c.status === 'Code copied.' ? <Check className="size-4" /> : <Copy className="size-4" />}
        </Button>
      )}
      {c.downloadable && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label="Download code"
          onClick={() => {
            const url = URL.createObjectURL(
                new Blob([c.code], { type: 'text/plain;charset=utf-8' }),
              ),
              link = document.createElement('a')
            link.href = url
            link.download = c.filename || 'code.txt'
            link.click()
            setTimeout(() => URL.revokeObjectURL(url), 1000)
          }}
        >
          <Download className="size-4" />
        </Button>
      )}
    </figcaption>
  )
}
/** Renders line numbers separately from selectable code, with optional line emphasis and wrapping. */
export function CodeBlockContent({ className, ...props }: React.ComponentProps<'pre'>) {
  const c = useCode(),
    lines = c.code.split('\n')
  return (
    <pre
      {...props}
      dir="ltr"
      tabIndex={0}
      className={cn(
        'max-h-[36rem] overflow-auto py-4 text-left text-[13px] leading-6',
        c.wrap ? 'whitespace-pre-wrap break-words' : 'whitespace-pre',
        className,
      )}
    >
      <code className="block">
        {lines.map((line, index) => (
          <span
            key={index}
            data-line={c.startLine + index}
            className={cn(
              'flex min-h-6 px-4',
              c.highlightedLines.includes(c.startLine + index) &&
                'bg-primary/10 shadow-[inset_3px_0_0_var(--primary)]',
            )}
          >
            {c.lineNumbers && (
              <span
                aria-hidden="true"
                className="me-5 w-8 shrink-0 select-none text-right text-muted-foreground/60"
              >
                {c.startLine + index}
              </span>
            )}
            <span className="min-w-0 flex-1">
              {c.tokens?.[index]
                ? c.tokens[index].map((token, i) => (
                    <span
                      key={i}
                      className="[color:var(--code-light)] dark:[color:var(--code-dark)]"
                      style={
                        {
                          '--code-light': `color-mix(in srgb,${token.variants.light?.color ?? 'var(--foreground)'} 80%,var(--foreground))`,
                          '--code-dark': `color-mix(in srgb,${token.variants.dark?.color ?? 'var(--foreground)'} 80%,var(--foreground))`,
                          fontStyle:
                            (token.variants.light?.fontStyle ?? 0) & 1 ? 'italic' : undefined,
                          fontWeight:
                            (token.variants.light?.fontStyle ?? 0) & 2 ? 'bold' : undefined,
                        } as React.CSSProperties
                      }
                    >
                      {token.content}
                    </span>
                  ))
                : line}
            </span>
            {index < lines.length - 1 ? '\n' : null}
          </span>
        ))}
      </code>
    </pre>
  )
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import type { HighlighterCore, ThemedTokenWithVariants } from 'shiki/core'

export const codeLanguages = [
  'text',
  'javascript',
  'jsx',
  'typescript',
  'tsx',
  'json',
  'css',
  'html',
  'markdown',
  'bash',
  'yaml',
  'sql',
  'python',
] as const
export type CodeLanguage = (typeof codeLanguages)[number]
const loaders = {
  javascript: () => import('shiki/langs/javascript.mjs'),
  jsx: () => import('shiki/langs/jsx.mjs'),
  typescript: () => import('shiki/langs/typescript.mjs'),
  tsx: () => import('shiki/langs/tsx.mjs'),
  json: () => import('shiki/langs/json.mjs'),
  css: () => import('shiki/langs/css.mjs'),
  html: () => import('shiki/langs/html.mjs'),
  markdown: () => import('shiki/langs/markdown.mjs'),
  bash: () => import('shiki/langs/bash.mjs'),
  yaml: () => import('shiki/langs/yaml.mjs'),
  sql: () => import('shiki/langs/sql.mjs'),
  python: () => import('shiki/langs/python.mjs'),
}
let highlighter: Promise<HighlighterCore> | undefined
const loading = new Map<string, Promise<void>>()
/** Loads the JavaScript regex engine, two themes, and only the requested grammar on demand. */
export async function highlightCode(
  code: string,
  language: CodeLanguage,
): Promise<ThemedTokenWithVariants[][]> {
  if (language === 'text')
    return code
      .split('\n')
      .map((content) => [{ content, offset: 0, variants: { light: {}, dark: {} } }])
  if (!codeLanguages.includes(language)) throw new Error(`Unsupported language: ${language}`)
  highlighter ??= Promise.all([
    import('shiki/core'),
    import('shiki/engine/javascript'),
    import('shiki/themes/github-light.mjs'),
    import('shiki/themes/github-dark.mjs'),
  ])
    .then(([core, engine, light, dark]) =>
      core.createHighlighterCore({
        themes: [light.default, dark.default],
        langs: [],
        engine: engine.createJavaScriptRegexEngine({ forgiving: true }),
      }),
    )
    .catch((error) => {
      highlighter = undefined
      throw error
    })
  const instance = await highlighter
  if (!loading.has(language))
    loading.set(
      language,
      loaders[language]()
        .then((grammar) => instance.loadLanguage(grammar.default))
        .catch((error) => {
          loading.delete(language)
          throw error
        }),
    )
  await loading.get(language)
  return instance.codeToTokensWithThemes(code, {
    lang: language,
    themes: { light: 'github-light', dark: 'github-dark' },
  })
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
  const set = React.useCallback((next: T | ((previous: T) => T)) => {
    const previous = currentRef.current
    const result = typeof next === 'function' ? (next as (previous: T) => T)(previous) : next
    if (Object.is(previous, result)) return
    currentRef.current = result
    if (valueRef.current === undefined) setInternal(result)
    changeRef.current?.(result)
  }, [])
  return [current, set] as const
}
export function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  React.useEffect(() => {
    const m = window.matchMedia(query)
    const update = () => setMatches(m.matches)
    update()
    m.addEventListener('change', update)
    return () => m.removeEventListener('change', update)
  }, [query])
  return matches
}
export function useDebouncedValue<T>(value: T, delay = 250) {
  const [debounced, set] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => set(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}
export async function copyToClipboard(text: string) {
  await navigator.clipboard.writeText(text)
}
export function useBreakpoints() {
  const [width, setWidth] = React.useState(() =>
    typeof window === 'undefined' ? 0 : window.innerWidth,
  )
  React.useEffect(() => {
    const update = () => setWidth(window.innerWidth)
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])
  return Object.fromEntries(
    Object.entries(breakpoints).map(([key, min]) => [key, width >= min]),
  ) as Record<Breakpoint, boolean>
}

import type { CSSProperties } from 'react'
export const breakpoints = { xs: 0, sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536 } as const
export type Breakpoint = keyof typeof breakpoints
export type Responsive<T> = T | Partial<Record<Breakpoint, T>>
export function responsiveStyle<T>(value: Responsive<T> | undefined, name: string): CSSProperties {
  if (value === undefined) return {}
  const values = typeof value === 'object' && value !== null ? value : { xs: value }
  return Object.fromEntries(
    Object.entries(values).map(([key, v]) => [`--${name}-${key}`, v]),
  ) as CSSProperties
}
export const responsiveCSS = Object.entries(breakpoints)
  .map(([, min], index) => {
    const fallback = (name: string, initial: string) =>
      Object.keys(breakpoints)
        .slice(0, index + 1)
        .reduce((result, key) => `var(--${name}-${key},${result})`, initial)
    return `@media(min-width:${min}px){.ergon-col{width:calc(${fallback('span', '24')} / 24 * 100%);margin-inline-start:calc(${fallback('offset', '0')} / 24 * 100%);order:${fallback('order', '0')}}.ergon-flex{gap:${fallback('gap', '12px')};flex-direction:${fallback('direction', 'row')}}}`
  })
  .join('')

import * as React from 'react'
import { useControllableState } from '@/components/ui/util'

/** Runs the latest cancellable action without publishing stale results after unmount. */
export function useAsyncAction() {
  const active = React.useRef<AbortController | null>(null)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState('')
  React.useEffect(
    () => () => {
      active.current?.abort()
      active.current = null
    },
    [],
  )
  const cancel = React.useCallback(() => {
    active.current?.abort()
    active.current = null
    setBusy(false)
  }, [])
  const run = React.useCallback(async <T>(task: (signal: AbortSignal) => T | Promise<T>) => {
    active.current?.abort()
    const controller = new AbortController()
    active.current = controller
    setBusy(true)
    setError('')
    try {
      const value = await task(controller.signal)
      if (!controller.signal.aborted && active.current === controller) return value
    } catch (failure) {
      if (!controller.signal.aborted && active.current === controller)
        setError(failure instanceof Error ? failure.message : 'The action failed.')
    } finally {
      if (active.current === controller) {
        active.current = null
        setBusy(false)
      }
    }
    return undefined
  }, [])
  return { busy, error, run, cancel, clearError: () => setError('') }
}

/** Bounded immutable history for controlled or uncontrolled editors. */
export function useEditorHistory<T>({
  value,
  defaultValue,
  onChange,
  limit = 50,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
  limit?: number
}) {
  const [current, setCurrent] = useControllableState({ value, defaultValue, onChange })
  const [past, setPast] = React.useState<T[]>([])
  const [future, setFuture] = React.useState<T[]>([])
  const expected = React.useRef(current)
  React.useEffect(() => {
    if (value !== undefined && value !== expected.current) {
      expected.current = value
      setPast([])
      setFuture([])
    }
  }, [value])
  const apply = (next: T) => {
    expected.current = next
    setCurrent(next)
  }
  return {
    value: current,
    canUndo: past.length > 0,
    canRedo: future.length > 0,
    commit(next: T) {
      if (Object.is(next, current)) return
      setPast((previous) => [...previous, current].slice(-Math.max(1, Math.min(100, limit))))
      setFuture([])
      apply(next)
    },
    undo() {
      if (!past.length) return
      setPast(past.slice(0, -1))
      setFuture([current, ...future])
      apply(past[past.length - 1])
    },
    redo() {
      if (!future.length) return
      setPast([...past, current])
      setFuture(future.slice(1))
      apply(future[0])
    },
  }
}

/** Accepts explicit web/blob/image URLs and relative paths, never executable protocols. */
export function productURL(value: string, image = false): string | undefined {
  const clean = value.trim()
  if (
    !clean ||
    [...clean].some((character) => character.charCodeAt(0) <= 32 || character.charCodeAt(0) === 127)
  )
    return
  if (image && /^data:image\/(?:png|jpeg|webp|gif);base64,[\da-z+/=]+$/i.test(clean)) return clean
  try {
    const url = new URL(clean, 'https://ergon.invalid/')
    if (['http:', 'https:'].includes(url.protocol) || (image && url.protocol === 'blob:'))
      return clean
  } catch {
    /* Invalid input remains inert. */
  }
}
export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))
/** Creates client-side entity IDs in secure and plain-HTTP browser contexts. */
export const productId = () => {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID()
  const bytes = globalThis.crypto.getRandomValues(new Uint8Array(16))
  bytes[6] = (bytes[6] & 15) | 64
  bytes[8] = (bytes[8] & 63) | 128
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

import * as React from 'react'

export interface TextStreamOptions {
  /** Reveal incoming text progressively, or display each received chunk immediately. */
  textAnimation?: 'typewriter' | 'none'
  /** Graphemes revealed per second, from 1 to 1,000. Defaults to 60. */
  charactersPerSecond?: number
}

/** Keeps network chunks separate from presentation. Completed history is displayed immediately. */
export function useTextStream(
  content: string,
  {
    streaming = false,
    textAnimation = 'typewriter',
    charactersPerSecond = 60,
    streamKey,
    immediate = false,
  }: TextStreamOptions & {
    streaming?: boolean
    streamKey?: string | number
    immediate?: boolean
  } = {},
) {
  // Older engines without grapheme segmentation fall back to immediate, intact text.
  const enabled =
    textAnimation === 'typewriter' && !immediate && typeof Intl.Segmenter === 'function'
  const boundaries = React.useMemo(() => {
    const offsets = [0]
    if (!enabled) return content ? [0, content.length] : offsets
    // Segment once per received chunk, never once per animation frame.
    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' })
    for (const part of segmenter.segment(content)) offsets.push(part.index + part.segment.length)
    return offsets
  }, [content, enabled])
  const length = boundaries.length - 1
  const [state, setState] = React.useState(() => ({
    content,
    streamKey,
    enabled,
    streaming,
    index: enabled && streaming ? 0 : length,
    session: enabled && streaming,
    epoch: 0,
  }))
  if (
    state.content !== content ||
    state.streamKey !== streamKey ||
    state.enabled !== enabled ||
    state.streaming !== streaming
  ) {
    const reset = state.streamKey !== streamKey || !content.startsWith(state.content)
    const session = enabled && (streaming || (!reset && state.session))
    const index = session && state.enabled ? (reset ? 0 : Math.min(state.index, length)) : length
    setState({
      content,
      streamKey,
      enabled,
      streaming,
      index,
      session: session && (streaming || index < length),
      epoch: reset ? state.epoch + 1 : state.epoch,
    })
  }
  const latest = React.useRef({ length, streaming })
  React.useLayoutEffect(() => {
    latest.current = { length, streaming }
  })
  const pending = enabled && state.session && state.index < length
  const rate = Number.isFinite(charactersPerSecond)
    ? Math.min(1000, Math.max(1, charactersPerSecond))
    : 60
  React.useEffect(() => {
    if (!pending) return
    let previous = performance.now(),
      credit = 0
    const timer = setInterval(() => {
      const now = performance.now()
      credit += ((now - previous) * rate) / 1000
      previous = now
      const count = Math.floor(credit)
      if (!count) return
      credit -= count
      setState((current) => {
        const index = Math.min(latest.current.length, current.index + count)
        return {
          ...current,
          index,
          session: latest.current.streaming || index < latest.current.length,
        }
      })
    }, 16)
    return () => clearInterval(timer)
  }, [pending, rate, state.epoch])
  return {
    text:
      enabled && state.session
        ? content.slice(0, boundaries[Math.min(state.index, length)])
        : content,
    isRevealing: pending,
  }
}
